async function api(action:string,data:any={}){const r=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,...data})});let j:any;try{j=await r.json();}catch{throw Error('Server unavailable. Please try again.');}if(!r.ok)throw Error(j.error||'Request failed');return j;}
function download(name:string,text:string,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
