 const [appLang,setAppLang]=useState<string>('en'),[page,setPage]=useState('Home'),[records,setRecords]=useState<Rec[]>([]),[profile,setProfile]=useState<any>(null),[keys,setKeys]=useState<any[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState(''),[toast,setToast]=useState(''),[dark,setDark]=useState(false),[mobile,setMobile]=useState(false);
 const [entry,setEntry]=useState<any>(null),[entryId,setEntryId]=useState(''),[query,setQuery]=useState(''),[trash,setTrash]=useState(false),[dateFilter,setDateFilter]=useState(''),[saveState,setSaveState]=useState(''),[voiceState,setVoiceState]=useState<VoiceState>('idle'),[voiceMessage,setVoiceMessage]=useState(''),[voiceInterim,setVoiceInterim]=useState(''),[voiceConsent,setVoiceConsent]=useState(false),[speechLang,setSpeechLang]=useState('en-IN');const recognition=useRef<any>(null),dirty=useRef(false),entryRef=useRef<any>(null),saving=useRef(false);
 const [plan,setPlan]=useState<any>(null),[planId,setPlanId]=useState(''),[post,setPost]=useState<any>(null),[view,setView]=useState('grid'),[status,setStatus]=useState('All'),[selected,setSelected]=useState<string[]>([]),[busy,setBusy]=useState(false),[form,setForm]=useState<any>({brand:'',topic:'',platform:'Instagram',tone:'Friendly',audience:'',language:'English',start:today(),provider:'openrouter',goal:'Balanced education, promotion and engagement',instructions:'',fallback:false,mode:'single'});
 const [provider,setProvider]=useState('openrouter'),[keyText,setKeyText]=useState(''),[model,setModel]=useState(''),[modelList,setModelList]=useState<any[]>([]),[account,setAccount]=useState<any>({name:'',username:'',bio:'',avatar:''});
 const [users,setUsers]=useState<any[]>([]),[threads,setThreads]=useState<any[]>([]),[peer,setPeer]=useState<any>(null),[messages,setMessages]=useState<any[]>([]),[self,setSelf]=useState(''),[message,setMessage]=useState(''),[userSearch,setUserSearch]=useState(''),[chatRequest,setChatRequest]=useState<any>(null),[chatPinned,setChatPinned]=useState(false),[chatVoice,setChatVoice]=useState(false);const end=useRef<HTMLDivElement>(null),chatRecognition=useRef<any>(null);
