 async function load(){try{const j=await api('load');setRecords(j.records);setProfile(j.profile);setKeys(j.keys);const detectedLang = j.profile?.language || (typeof window !== 'undefined' ? localStorage.getItem('diary_app_lang') : '') || detectAutoLanguage(navigator.language, j.profile?.country);
      setAppLang(detectedLang);
      if(typeof window !== 'undefined') localStorage.setItem('diary_app_lang', detectedLang);
      setAccount(j.profile||{name:j.name,username:'',bio:'',avatar:'',country:'',language:detectedLang,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||''});if(!j.profile)setPage('Profile');}catch(e){fail(e);}finally{setLoading(false);}}
 useEffect(()=>{load();const theme=localStorage.getItem('diary-theme');setDark(theme==='dark');},[]);
 useEffect(()=>{document.documentElement.dataset.theme=dark?'dark':'light';localStorage.setItem('diary-theme',dark?'dark':'light');},[dark]);
 const diaries=records.filter(r=>r.kind==='diary'),plans=records.filter(r=>r.kind==='calendar'&&!r.data.deleted),brands=records.filter(r=>r.kind==='brand'&&!r.data.deleted);
 async function persist(kind:string,data:any,id?:string){const j=await api('save',{kind,data,id});setRecords(old=>[{id:j.id,kind,data,updated:Date.now()},...old.filter(x=>x.id!==j.id)]);return j.id;}
 function newEntry(){if(dirty.current){notify('Save the current diary entry before creating another.');return;}dirty.current=false;const e={title:'',body:'',date:today(),mood:'😌',tags:'',favorite:false,photos:[]};setEntryId(crypto.randomUUID());setEntry(e);entryRef.current=e;setSaveState('New entry');setPage('My diary');}
 function changeEntry(patch:any){const next={...entryRef.current,...patch};entryRef.current=next;setEntry(next);dirty.current=true;setSaveState('Unsaved changes');}
