 useEffect(()=>{if(!entry)return;const t=setInterval(()=>{if(dirty.current)saveEntry();},3000);return()=>clearInterval(t);},[entryId,!!entry]);
 useEffect(()=>{const warn=(e:BeforeUnloadEvent)=>{if(dirty.current){e.preventDefault();e.returnValue='';}};window.addEventListener('beforeunload',warn);return()=>window.removeEventListener('beforeunload',warn);},[]);
 async function leaveEntry(){await saveEntry();if(dirty.current)return;recognition.current?.abort();setVoiceState('idle');setVoiceInterim('');setEntry(null);}
 async function go(p:string){if(entry){await saveEntry();if(dirty.current)return;}recognition.current?.abort();setVoiceState('idle');setVoiceInterim('');setPage(p);setMobile(false);setQuery('');}
 function openEntry(r:Rec){setEntryId(r.id);setEntry(r.data);entryRef.current=r.data;dirty.current=false;setSaveState('All changes saved');setPage('My diary');}
 async function archive(r:Rec){await persist(r.kind,{...r.data,deleted:!r.data.deleted},r.id);notify(r.data.deleted?'Restored':'Moved to trash');}
 function dictation(){
 if(['starting','listening','stopping'].includes(voiceState)){recognition.current?.stop();return;}
 setVoiceMessage('');setVoiceInterim('');
 const SR=(window as any).SpeechRecognition||(window as any).webkitSpeechRecognition;
 if(!window.isSecureContext){setVoiceState('error');setVoiceMessage('Microphone access requires HTTPS. Open the secure app link in a separate browser tab.');return;}
 if(!SR){setVoiceState('error');setVoiceMessage('This browser does not provide voice typing. Try the latest Chrome in a separate tab, or use your device keyboard dictation.');return;}
 const policy=(document as any).permissionsPolicy||(document as any).featurePolicy;
 if(policy?.allowsFeature&&!policy.allowsFeature('microphone')){setVoiceState('error');setVoiceMessage('Microphone access is blocked in this embedded view. Open the app in a separate tab, then allow the microphone.');return;}
 if(!/^[a-z]{2,3}(?:-[A-Za-z0-9]{2,8})*$/.test(speechLang.trim())){setVoiceState('error');setVoiceMessage('Choose a language code such as hi-IN, en-IN or zh-CN.');return;}
 setVoiceConsent(true);
 }
 function startVoice(){setVoiceConsent(false);recognition.current?.abort();const SR=(window as any).SpeechRecognition||(window as any).webkitSpeechRecognition;
 try{recognition.current=createDictation(SR,speechLang.trim(),{state:setVoiceState,message:setVoiceMessage,interim:setVoiceInterim,append:text=>{const current=entryRef.current;if(!current)return;changeEntry({body:(current.body||'')+((current.body||'').endsWith(' ')||!current.body?'':' ')+text});}});recognition.current.start();}catch{setVoiceState('error');setVoiceMessage('Voice typing could not initialize. Open this app in a separate browser tab and try again.');}}
 useEffect(()=>()=>{recognition.current?.abort();},[]);

