 async function savePost(){const old=plan.posts.find((p:any)=>p.id===post.id);const updated={...post,history:[...(old.history||[]),{...old,history:undefined}].slice(-10)};await savePlan({...plan,posts:plan.posts.map((p:any)=>p.id===post.id?updated:p)});setPost(null);notify('Post saved');}
 async function rewrite(text:string,instruction:string,callback:(s:string)=>void){if(!keys.length){notify('Connect an AI provider in Settings first');return;}setBusy(true);try{const j=await api('rewrite',{text,instruction,provider:form.provider,fallback:form.fallback});callback(j.text);notify('Rewritten using '+j.provider);}catch(e){fail(e);}finally{setBusy(false);}}
 function exportPlan(format:string){if(format==='pdf'){window.print();return;}if(format==='json'){download('content-calendar.json',JSON.stringify(plan,null,2));return;}const cols=['day','date','contentType','topic','caption','hashtags','time','status'];const cell=(v:any)=>{let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};download('content-calendar.csv','\uFEFF'+[cols.join(','),...plan.posts.map((p:any)=>cols.map(c=>cell(p[c])).join(','))].join('\r\n'),'text/csv;charset=utf-8');}
