 function toggleChatVoice(){const SR=(window as any).SpeechRecognition||(window as any).webkitSpeechRecognition;if(!SR){notify('Voice typing is not supported in this browser. Try Google Chrome.');return;}if(chatVoice){chatRecognition.current?.stop();setChatVoice(false);return;}try{const rec=new SR();rec.lang=speechLang||'en-IN';rec.continuous=true;rec.interimResults=true;rec.onresult=(ev:any)=>{let str='';for(let i=ev.resultIndex;i<ev.results.length;++i){if(ev.results[i].isFinal)str+=ev.results[i][0].transcript;}if(str){setMessage(prev=>(prev?prev+' ':'')+str.trim());}};rec.onerror=()=>setChatVoice(false);rec.onend=()=>setChatVoice(false);chatRecognition.current=rec;rec.start();setChatVoice(true);notify('Microphone on: speak now! (boliye)');}catch{setChatVoice(false);notify('Microphone access blocked or unavailable.');}}
