 const customField=(label:string,name:string,choices:string[],hint:string)=><label>{label}<input required maxLength={120} list={name+'-options'} value={form[name]} placeholder={'Search or type '+label.toLowerCase()} onChange={e=>setForm({...form,[name]:e.target.value})}/><datalist id={name+'-options'}>{choices.map(x=><option key={x} value={x}/>)}</datalist><small>{hint}</small></label>;
