 async function saveProfileData(accToSave:any){try{await api('profile',accToSave);setProfile({...accToSave});await load();notify('Profile and photo saved successfully');}catch(e){fail(e);}}
 function handlePhoto(e:React.ChangeEvent<HTMLInputElement>){const f=e.target.files?.[0];if(!f)return;e.target.value='';const url=URL.createObjectURL(f);const img=new Image();img.onload=async()=>{try{const canvas=document.createElement('canvas');const size=256;canvas.width=size;canvas.height=size;const ctx=canvas.getContext('2d');if(!ctx){URL.revokeObjectURL(url);notify('Could not process photo');return;}const minDim=Math.min(img.width,img.height);const sx=(img.width-minDim)/2;const sy=(img.height-minDim)/2;ctx.drawImage(img,sx,sy,minDim,minDim,0,0,size,size);const compressed=canvas.toDataURL('image/jpeg',0.85);URL.revokeObjectURL(url);const updated={...account,avatar:compressed};setAccount(updated);await api('profile',updated);setProfile((prev:any)=>({...prev,avatar:compressed}));notify('Profile photo updated & saved! 📸');}catch(err:any){URL.revokeObjectURL(url);fail(err);}};img.onerror=()=>{URL.revokeObjectURL(url);notify('Invalid image file');};img.src=url;}
